<template><div class="container-fluid"><div class="mb-3"><h4 class="mb-1">Finance, tax & accounting</h4><div class="text-muted small">Operating expenses, tax summaries, income statement, journals and backup status.</div></div>
<ul class="nav nav-tabs mb-3"><li class="nav-item" v-for="t in tabs" :key="t.key"><button class="nav-link" :class="{active:tab===t.key}" @click="tab=t.key;load()">{{t.label}}</button></li></ul>
<div v-if="tab==='expenses'" class="card"><div class="card-header fw-semibold">Record operating expense</div><form class="card-body row g-2" @submit.prevent="saveExpense"><div class="col-md-2"><input v-model="expense.category" class="form-control" placeholder="Category" required></div><div class="col-md-3"><input v-model="expense.description" class="form-control" placeholder="Description" required></div><div class="col-md-2"><input v-model.number="expense.amount" type="number" min=".01" step=".01" class="form-control" placeholder="Amount" required></div><div class="col-md-2"><input v-model="expense.expense_date" type="date" class="form-control" required></div><div class="col-md-2"><select v-model="expense.payment_method" class="form-select"><option value="cash">Cash</option><option value="bank">Bank</option><option value="card">Card</option><option value="online">Online</option></select></div><div class="col-md-1"><button class="btn btn-success w-100">Save</button></div></form><div class="table-responsive"><table class="table mb-0"><thead><tr><th>Date</th><th>Category</th><th>Description</th><th class="text-end">Amount</th></tr></thead><tbody><tr v-for="e in expenses" :key="e.id"><td>{{e.expense_date}}</td><td>{{e.category}}</td><td>{{e.description}}</td><td class="text-end">{{money(e.amount)}}</td></tr></tbody></table></div></div>
<div v-else-if="tab==='tax'" class="card"><div class="card-header fw-semibold">Tax profiles</div><form class="card-body row g-2" @submit.prevent="saveTax"><div class="col-md-3"><input v-model="tax.name" class="form-control" placeholder="Tax name" required></div><div class="col-md-2"><input v-model="tax.tax_code" class="form-control" placeholder="Tax code" required></div><div class="col-md-2"><input v-model.number="tax.rate" type="number" min="0" max="100" step=".001" class="form-control" placeholder="Rate %" required></div><div class="col-md-3"><select v-model="tax.calculation" class="form-select"><option value="exclusive">Tax exclusive</option><option value="inclusive">Tax inclusive</option></select></div><div class="col-md-2"><div class="form-check"><input id="taxDefault" v-model="tax.is_default" type="checkbox" class="form-check-input"><label for="taxDefault" class="form-check-label small">Default</label></div><button class="btn btn-success w-100 mt-1">Add tax</button></div></form><div class="table-responsive"><table class="table mb-0"><thead><tr><th>Name</th><th>Code</th><th>Rate</th><th>Calculation</th><th>Status</th></tr></thead><tbody><tr v-for="t in taxes" :key="t.id"><td>{{t.name}}</td><td>{{t.tax_code}}</td><td>{{t.rate}}%</td><td>{{t.calculation}}</td><td>{{t.is_active?'Active':'Inactive'}}</td></tr></tbody></table></div><div class="card-footer"><b>Tax summary:</b> Sales tax {{money(taxReport.sales_tax)}} · Input tax {{money(taxReport.purchase_tax)}} · Net payable {{money(taxReport.net_tax_payable)}}</div></div>
<div v-else-if="tab==='statements'" class="card"><div class="card-header fw-semibold">Income statement</div><div class="card-body"><div class="row g-2 mb-3"><div class="col-md-4"><label class="form-label">From</label><input v-model="period.from" type="date" class="form-control"></div><div class="col-md-4"><label class="form-label">To</label><input v-model="period.to" type="date" class="form-control"></div><div class="col-md-4 d-flex align-items-end"><button class="btn btn-success" @click="loadStatement">Generate statement</button></div></div><div class="row g-3"><div v-for="(v,k) in statement" :key="k" class="col-md-4"><div v-if="typeof v === 'number'" class="border rounded p-3"><div class="small text-muted text-capitalize">{{k.replaceAll('_',' ')}}</div><div class="fs-5 fw-bold">{{money(v)}}</div></div></div></div><hr><h6>Cash flow summary</h6><div class="row g-3"><div v-for="(v,k) in cashflow" :key="k" class="col-md-4"><div v-if="typeof v === 'number'" class="border rounded p-3"><div class="small text-muted text-capitalize">{{k.replaceAll('_',' ')}}</div><div class="fw-bold">{{money(v)}}</div></div></div></div></div></div>
<div v-else-if="tab==='balance'" class="card"><div class="card-header fw-semibold">Balance sheet</div><div class="card-body"><div class="row g-2 align-items-end mb-3"><div class="col-md-4"><label class="form-label">As of date</label><input v-model="balanceDate" type="date" class="form-control"></div><div class="col-md-3"><button class="btn btn-success" @click="loadBalance">Generate</button></div></div><div class="row g-3 mb-3"><div class="col-md-4"><div class="border rounded p-3">Assets <b class="d-block fs-5">{{money(balance.assets)}}</b></div></div><div class="col-md-4"><div class="border rounded p-3">Liabilities <b class="d-block fs-5">{{money(balance.liabilities)}}</b></div></div><div class="col-md-4"><div class="border rounded p-3">Equity <b class="d-block fs-5">{{money(balance.equity)}}</b></div></div></div><table class="table"><thead><tr><th>Account</th><th>Type</th><th class="text-end">Balance</th></tr></thead><tbody><tr v-for="a in balance.data||[]" :key="a.id"><td>{{a.code}} · {{a.name}}</td><td>{{a.type}}</td><td class="text-end">{{money(a.balance)}}</td></tr></tbody></table><div class="small text-muted">Balance sheet includes automatically posted operational journals and manual entries. Enter verified opening balances before relying on it; historical records are not automatically backfilled.</div></div></div>
<div v-else-if="tab==='journals'" class="card"><div class="card-header fw-semibold">Manual journal entries</div><div class="card-body"><div class="alert alert-info small">Sales, purchases, payments, returns, expenses and stock adjustments post balanced journals automatically. Use manual journals for opening balances and approved adjustments.</div><div class="row g-2"><div class="col-md-5"><input v-model="journal.narration" class="form-control" placeholder="Journal narration"></div><div class="col-md-3"><input v-model="journal.entry_date" type="date" class="form-control"></div><div class="col-md-4"><button class="btn btn-success" @click="postJournal">Post balanced journal</button></div></div><div class="row g-2 mt-2"><div class="col-md-5"><select v-model.number="journal.debit_account" class="form-select"><option value="">Debit account</option><option v-for="a in accounts" :key="a.id" :value="a.id">{{a.code}} · {{a.name}}</option></select></div><div class="col-md-2"><input v-model.number="journal.amount" type="number" min=".01" step=".01" class="form-control" placeholder="Amount"></div><div class="col-md-5"><select v-model.number="journal.credit_account" class="form-select"><option value="">Credit account</option><option v-for="a in accounts" :key="a.id" :value="a.id">{{a.code}} · {{a.name}}</option></select></div></div></div><div class="table-responsive"><table class="table mb-0"><thead><tr><th>Entry</th><th>Date</th><th>Narration</th><th>Status</th></tr></thead><tbody><tr v-for="j in journals" :key="j.id"><td>{{j.entry_no}}</td><td>{{j.entry_date}}</td><td>{{j.narration}}</td><td>{{j.status}}</td></tr></tbody></table></div><div class="card-body border-top"><h6>Trial balance</h6><div class="table-responsive"><table class="table table-sm"><thead><tr><th>Account</th><th class="text-end">Debit</th><th class="text-end">Credit</th></tr></thead><tbody><tr v-for="a in trialBalance" :key="a.id"><td>{{a.code}} · {{a.name}}</td><td class="text-end">{{money(a.debit_total||0)}}</td><td class="text-end">{{money(a.credit_total||0)}}</td></tr></tbody></table></div></div></div>
<div v-else class="card"><div class="card-header fw-semibold">Encrypted cloud backups</div><div class="table-responsive"><table class="table mb-0"><thead><tr><th>Completed</th><th>Cloud disk</th><th>Path</th><th>Size</th><th>Status</th><th>Message</th></tr></thead><tbody><tr v-for="b in backups" :key="b.id"><td>{{b.completed_at}}</td><td>{{b.disk}}</td><td class="text-break">{{b.path}}</td><td>{{b.size_bytes?Math.round(b.size_bytes/1024)+' KB':'—'}}</td><td><span class="badge" :class="b.status==='success'?'bg-success':'bg-danger'">{{b.status}}</span></td><td>{{b.message}}</td></tr></tbody></table></div><div class="card-footer small text-muted">Run <code>php artisan store:backup-cloud</code> to test the configured S3-compatible backup destination.</div></div>
</div></template>
<script setup>
import {onMounted,reactive,ref} from 'vue';import api from '../api';import {money} from '../utils/format';const today=new Date().toISOString().slice(0,10);const tabs=[{key:'expenses',label:'Expenses'},{key:'tax',label:'Tax'},{key:'statements',label:'Financial statements'},{key:'balance',label:'Balance sheet'}, {key:'journals',label:'Journals'},{key:'backups',label:'Backups'}];const tab=ref('expenses'),expenses=ref([]),taxes=ref([]),journals=ref([]),backups=ref([]),accounts=ref([]),trialBalance=ref([]),taxReport=ref({}),statement=ref({}),cashflow=ref({}),balance=ref({data:[]}),balanceDate=ref(today);const expense=reactive({category:'',description:'',amount:0,expense_date:today,payment_method:'cash'}),tax=reactive({name:'',tax_code:'',rate:0,calculation:'exclusive',is_active:true,is_default:false}),period=reactive({from:today.slice(0,8)+'01',to:today}),journal=reactive({narration:'',entry_date:today,debit_account:'',credit_account:'',amount:0});
async function load(){if(tab.value==='expenses')expenses.value=(await api.get('/expenses')).data.data||[];if(tab.value==='tax'){taxes.value=(await api.get('/tax-profiles')).data;taxReport.value=(await api.get('/reports/tax')).data;}if(tab.value==='statements')await loadStatement();if(tab.value==='balance')await loadBalance();if(tab.value==='journals'){ const [j,a,t]=await Promise.all([api.get('/accounting/journals'),api.get('/accounting/accounts'),api.get('/accounting/trial-balance')]);journals.value=j.data.data||[];accounts.value=a.data;trialBalance.value=t.data.data||[];}if(tab.value==='backups')backups.value=(await api.get('/backups')).data.data||[];}async function saveExpense(){await api.post('/expenses',expense);expense.description='';expense.amount=0;await load();}async function saveTax(){await api.post('/tax-profiles',tax);Object.assign(tax,{name:'',tax_code:'',rate:0,is_default:false});await load();}async function loadStatement(){const [s,c]=await Promise.all([api.get('/accounting/income-statement',{params:period}),api.get('/accounting/cash-flow',{params:period})]);statement.value=s.data;cashflow.value=c.data;}async function loadBalance(){balance.value=(await api.get('/accounting/balance-sheet',{params:{as_of:balanceDate.value}})).data;}async function postJournal(){if(!journal.narration||!journal.debit_account||!journal.credit_account||!journal.amount)return;await api.post('/accounting/journals',{entry_date:journal.entry_date,narration:journal.narration,lines:[{account_id:journal.debit_account,debit:journal.amount,credit:0},{account_id:journal.credit_account,debit:0,credit:journal.amount}]});journal.narration='';journal.amount=0;await load();}onMounted(load);
</script>
